  $('#tfGo').onclick=()=>{addVertexNumeric(+$('#tfL').value,+$('#tfA').value,$('#tfS')?+$('#tfS').value:1);$('#tfL').value='';$('#tfL').focus();};$('#tfL').onkeydown=e=>{if(e.key==='Enter'){e.stopPropagation();$('#tfGo').click();}};$('#tfA').onkeydown=e=>{if(e.key==='Enter'){e.stopPropagation();$('#tfGo').click();}};
