svg.addEventListener('wheel',e=>{e.preventDefault();const r=svg.getBoundingClientRect();const cx=e.clientX-r.left,cy=e.clientY-r.top;const f=e.deltaY<0?1.15:1/1.15;const v=state.view;const nk=Math.min(400,Math.max(0.05,v.k*f));const rr=nk/v.k;v.tx=cx-(cx-v.tx)*rr;v.ty=cy-(cy-v.ty)*rr;v.k=nk;applyView();render();save();},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA'||e.target.tagName==='SELECT')return;if(e.key==='Escape'){if(state.tracing){const wasResume=state.tracing.resume;state.tracing=null;renderDraft();renderTraceForm();if(wasResume){setMode('trace');flash('Reprise annulée — la ligne reste en pause');}}else if(state.mode!=='select')setMode('select');gDraft.innerHTML='';}
  if(e.key==='Enter'&&state.mode==='trace')finishTrace();if(e.key==='Backspace'&&state.tracing){const t=state.tracing;if(t.resume&&t.pts.length<=(t.base||0)){state.tracing=null;setMode('trace');flash('Reprise annulée — la ligne reste en pause (ses sommets se retirent dans sa fiche : ✕ sommet)');}else{t.pts.pop();if(!t.pts.length)state.tracing=null;}renderDraft();renderTraceForm();} /* 14/10 : en reprise, Retour arrière ne retire que les NOUVEAUX sommets */
  if((e.key==='p'||e.key==='P')&&state.tracing){pauseTrace();return;} /* 14/10 (édition du tracé) : P = mettre la ligne en pause */
  if((e.ctrlKey||e.metaKey)&&(e.key==='y'||e.key==='Y'||((e.key==='z'||e.key==='Z')&&e.shiftKey))){e.preventDefault();redo();return;} /* 14/10 soir (lot T1) : rétablir (Ctrl+Y, Ctrl+Maj+Z) */
  if((e.ctrlKey||e.metaKey)&&(e.key==='z'||e.key==='Z')){e.preventDefault();undo();return;}
  if(e.key==='t'||e.key==='T')setMode('trace');if(e.key==='s'||e.key==='S')setMode('select');if(e.key==='a'||e.key==='A')setMode('add');
  if(e.key==='Delete'){const sv=(state.selV||[])[0];if(sv){const l=state.lines.find(x=>x.id===sv.line);if(l)delVertex(l,sv.i);return;} /* 14/10 : même chemin que ✕ sommet (pièces recalées) */
    if(state.sel&&state.sel.kind==='line'&&confirm('Supprimer cette ligne ?'))delLine(state.sel.id);}});
const dedupePts=pts=>pts.filter((p,i)=>i===0||Math.hypot(p[0]-pts[i-1][0],p[1]-pts[i-1][1])>0.05);
/* 14/10 (édition du tracé) : validation du tracé en cours. pause=true → la ligne est créée (ou gardée) EN PAUSE : sommets déjà posés, pas de kit de bout, marqueur l.pause pour la reprendre.
   t.resume → on prolonge une ligne en pause : ses sommets sont remplacés par la polyligne complète (anciens + nouveaux), les pièces gardent leur PK (rien ne bouge avant le dernier sommet d'origine), les antennes restent accrochées. */
function commitTrace(pause){const t=state.tracing;if(!t)return false;const pts=dedupePts(t.pts);
  if(t.resume){const l=state.lines.find(x=>x.id===t.resume);if(!l){state.tracing=null;renderDraft();renderTraceForm();flash('Ligne introuvable');return false;}
    if(pts.length<2){flash('Il faut au moins deux sommets');return false;}
    snapshot();l.pts=pts;if(pause)l.pause=true;else delete l.pause;state.tracing=null;state.sel={kind:'line',id:l.id};state.tab='sel';rebuild();setMode('trace');
    flash(pause?`« ${l.name} » remise en pause (${fmt(polyLen(l.pts))} m) — ▶ Reprendre quand tu veux`:`« ${l.name} » terminée : ${fmt(polyLen(l.pts))} m, ${l.pts.length} sommets`);return true;}
  if(pts.length<2){if(!pause){state.tracing=null;renderDraft();renderTraceForm();}flash('Il faut au moins deux sommets');return false;}
  const id='L'+(state.seq++);const parentLine=t.parent?state.lines.find(x=>x.id===t.parent.line):null;const name=parentLine?`Antenne ${id}`:`Ligne ${id}`;
  const l={id,name,dn:state.dn,bar:state.bar,pts,specials:[],inv:true,parent:t.parent?{line:t.parent.line,m:t.parent.m,side:t.parent.side||1}:null}; /* 14/10 (Ethan) : aller À DROITE du sens de tracé par défaut (sur le terrain c'est le cas le plus courant) — seulement pour les NOUVELLES lignes : les tracés déjà enregistrés gardent leurs côtés et leurs n° de soudure ; bouton « ⇄ inverser » inchangé. DN / barre = valeurs du bandeau AU MOMENT de la validation (modifiables pendant le tracé). */
  if(pause)l.pause=true;state.lines.push(fonds.tagLine(l));/* 14/10 soir (T2) : l.plan */state.tracing=null;state.sel={kind:'line',id};state.tab='sel';rebuild();setMode('trace');
  if(pause)flash(`« ${name} » en pause (${fmt(polyLen(pts))} m, DN${l.dn}) : ＋ pour poser une purge, une vidange, un té… ou trace une antenne dessus ; ▶ Reprendre dans sa fiche, ou clic sur son dernier sommet`);return true;}
function finishTrace(){return commitTrace(false);}
function pauseTrace(){return commitTrace(true);}
// ▶ Reprendre une ligne en pause : on repart de son dernier sommet, les clics suivants la prolongent (Entrée = terminer, P = remettre en pause, Échap = la laisser en pause)
function resumeLine(id){const l=state.lines.find(x=>x.id===id);if(!l||l.pts.length<1)return false;if(!l.pause)l.pause=true;if(state.mode!=='trace')setMode('trace');else{state.tracing=null;}
  state.tracing={pts:l.pts.map(p=>p.slice()),base:l.pts.length,cursor:null,parent:null,resume:id,dn:l.dn,bar:l.bar||state.bar};state.sel={kind:'line',id};state.tab='sel';render();renderPanel();renderFoot();renderTraceForm();
  $('#hint').textContent=`▶ Reprise de « ${l.name} » (DN${l.dn}) : clique les sommets suivants — Entrée pour terminer, P pour remettre en pause, Échap pour la laisser en pause.`;return true;}
/* 14/10 (édition du tracé) : l'axe d'une ligne change (sommet supprimé) → chaque pièce, coupe et drapeau garde sa PLACE PHYSIQUE : point sur l'ancien axe → reprojeté sur le nouveau → nouveau PK.
   (Plus juste qu'un simple report proportionnel : une vanne posée devant un regard y reste.) Renvoie les pièces qui ont dû bouger de plus de 0,5 m (hors du nouvel axe : ramenées au plus près). */
function remapLine(l,oldPts){const moved=[];const re=(m,lbl)=>{const q=ptAt(oldPts,Math.max(0,Math.min(polyLen(oldPts),m)));const pr=projOnPoly(l.pts,[q.x,q.y]);if(pr.d>0.5&&lbl)moved.push(`${lbl} déplacée de ${fmt(pr.d)} m (PK ${fmt(pr.m)})`);return +pr.m.toFixed(3);};
  (l.specials||[]).forEach(sp=>{if(sp.atEnd)return;const lbl=sp.type==='tee'&&sp.vert?pvLabel(sp):sp.type==='tee'?'té':sp.type==='valve'?'vanne':sp.type==='reducer'?'réduction':sp.type;sp.m=re(sp.m,lbl);if(sp.mR!=null)sp.mR=re(sp.mR,null);});
  (l.cuts||[]).forEach(ct=>{ct.m=re(ct.m,null);});(l.drapeaux||[]).forEach(dp=>{dp.m0=re(dp.m0,'drapeau');dp.m1=Math.max(dp.m0+0.5,re(dp.m1,null));});return moved;}
// ✕ sommet : la ligne garde au moins 2 sommets ; le départ d'une antenne reste sur la parente ; les pièces restent à leur place (remapLine)
function delVertex(l,i){if(!l||!(i>=0&&i<l.pts.length))return false;if(l.pts.length<=2){flash('Une ligne garde au moins 2 sommets — supprime la ligne si elle ne sert plus');return false;}if(i===0&&l.parent){flash('Le départ d\'une antenne reste sur la parente (glisse-le le long de la parente, ou supprime l\'antenne)');return false;}
  snapshot();const old=l.pts.map(p=>p.slice());l.pts.splice(i,1);const moved=remapLine(l,old);state.selV=[];state.sel={kind:'line',id:l.id};rebuild();flash(`Sommet ${i} supprimé — ${l.pts.length} sommets, ${fmt(polyLen(l.pts))} m${moved.length?' · '+moved.join(' ; '):''}`);return true;}
/* ══ 23/10 (Ethan : « je supprime une lyre, j'ai quand même 4 soudures sur mon feeder plutôt qu'une barre » ; « décaler une lyre ou inverser son sens, petit raccourci » ;
   « sélectionner plusieurs sommets que l'on veut bouger ensemble ») ══
   · un sommet ALIGNÉ (angle ≈ 0°) coupe quand même la barre dans le moteur (déviation de 0°) → une soudure en trop par conduite ; rien ne bouge tout seul sur un
     chantier en cours : on le CHOISIT — ✂ dans la fiche de la soudure (retire le sommet), 🧹 dans la fiche de la ligne (tous les sommets alignés), 🗑 Supprimer la lyre ;
   · lyre / baïonnette (détection shapesIdx = celle des comptages) : barre ◀ ▶ décaler le long de l'axe, ⇅ inverser le côté (lyre), 🗑 ; les pièces gardent leur PK (remapLine) ;
   · ⊞ Sommets (bouton, t1Bar) : un clic ajoute / retire un sommet, un glisser déplace toute la sélection, un rectangle sélectionne les sommets englobés ; ◀ ▶ ▲ ▼ au mètre. */
const ALIGN_DEG=0.5;
function alignedVtx(l){const out=[];for(let i=1;i<l.pts.length-1;i++){if(Math.abs(turnDeg(l.pts[i-1],l.pts[i],l.pts[i+1]))<ALIGN_DEG)out.push(i);}return out;}
function delVertices(l,idx,lbl){const ids=[...new Set(idx)].filter(i=>i>=0&&i<l.pts.length&&!(i===0&&l.parent)).sort((a,b)=>b-a);if(!ids.length)return 0;if(l.pts.length-ids.length<2){flash('Une ligne garde au moins 2 sommets');return 0;}
  snapshot();const old=l.pts.map(p=>p.slice());ids.forEach(i=>l.pts.splice(i,1));const moved=remapLine(l,old);state.selV=[];state.sel={kind:'line',id:l.id};rebuild();shapeBar();flash(`${lbl||ids.length+' sommets retirés'} — ${l.pts.length} sommets, ${fmt(polyLen(l.pts))} m${moved.length?' · '+moved.join(' ; '):''}`);return ids.length;}
function weldDelHTML(w,l){if(!l||w.teeOut||w.bypass)return '';const n=l.pts.length;
  if(w.vtx!=null&&n>2){const a=Math.abs(w.dev||0);return `<div class="card" style="margin-top:6px"><div class="muted">Cette soudure vient du <b>sommet ${w.vtx}</b> de l'axe${a<ALIGN_DEG?' — <b>aligné (0°)</b> : il coupe la barre pour rien':` — déviation de ${fmt(a)}°`}.</div><button class="btn danger" data-act="delVertex" data-line="${l.id}" data-i="${w.vtx}" style="margin-top:6px">✂ Supprimer cette soudure (retire le sommet, la barre se recale)</button></div>`;}
  const B=state.built[l.id];const cd=B&&B[w.cond];const pa=cd&&cd.pieces[w.i],pb=cd&&cd.pieces[w.i+1];if(pa&&pb&&pa.kind==='tube'&&pb.kind==='tube')return `<div class="muted" style="margin-top:6px">Soudure du calepinage (barres de ${l.bar||state.bar} m) : pas supprimable — glisse-la pour la coulisser.</div>`;return '';}
function alignedHTML(l){const A=alignedVtx(l);if(!A.length)return '';return `<div class="note warn" style="margin-top:8px">⚠ ${A.length} sommet${A.length>1?'s':''} aligné${A.length>1?'s':''} (${A.join(', ')}) coupe${A.length>1?'nt':''} des barres pour rien : ${2*A.length} soudure${A.length>1?'s':''} en trop (aller + retour). <button class="btn sm" data-act="delAligned" data-line="${l.id}">🧹 Retirer ce${A.length>1?'s':''} ${A.length>1?A.length+' ':''}sommet${A.length>1?'s':''}</button></div>`;}
function multiVtxHTML(l){const V=state.selV||[];if(V.length<2)return '';const lines=[...new Set(V.map(v=>v.line))];const names=lines.map(id=>(state.lines.find(x=>x.id===id)||{}).name||id);
  return `<div class="card" style="margin-top:8px;border-color:#1c3d6b"><b>⊞ ${V.length} sommets sélectionnés</b> <span class="muted">(${names.map(esc).join(', ')})</span><div class="muted" style="margin:4px 0">Glisse l'un d'eux : ils bougent tous ensemble. Ou au mètre :</div><div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center"><button class="btn sm" data-act="nudge" data-dx="-1" data-dy="0">◀ 1 m</button><button class="btn sm" data-act="nudge" data-dx="1" data-dy="0">1 m ▶</button><button class="btn sm" data-act="nudge" data-dx="0" data-dy="-1">▲ 1 m</button><button class="btn sm" data-act="nudge" data-dx="0" data-dy="1">▼ 1 m</button><span style="width:1px;height:18px;background:var(--line)"></span><button class="btn sm" data-act="vtxNone">désélectionner</button><button class="btn sm danger" data-act="delSelVtx">🗑 Supprimer les ${V.length}</button></div></div>`;}
function nudgeSel(dx,dy){const V=state.selV||[];if(!V.length)return;snapshot();const byL={};V.forEach(v=>{(byL[v.line]=byL[v.line]||[]).push(v.i);});
  Object.keys(byL).forEach(id=>{const L=state.lines.find(x=>x.id===id);if(!L)return;const old=L.pts.map(p=>p.slice());byL[id].forEach(i=>{if(i===0&&L.parent)return;L.pts[i]=[L.pts[i][0]+dx,L.pts[i][1]+dy];});remapLine(L,old);});rebuild();shapeBar();}
/* lyre / baïonnette dont fait partie le sommet sélectionné */
function shapeOfSel(){const v=(state.selV||[])[0];if(!v||(state.selV||[]).length!==1)return null;const l=state.lines.find(x=>x.id===v.line);if(!l)return null;const SH=shapesIdx(l.pts);
  const ly=SH.lyres.find(x=>x.v.includes(v.i));if(ly)return {l,kind:'lyre',v:ly.v};const bj=SH.baio.find(x=>x.v.includes(v.i));if(bj)return {l,kind:'baio',v:bj.v};return null;}
function shapeAxis(sh){const P=sh.l.pts;const a=P[sh.v[0]],b=P[sh.v[sh.v.length-1]];let u=sh.kind==='lyre'?[b[0]-a[0],b[1]-a[1]]:(sh.v[0]>0?[a[0]-P[sh.v[0]-1][0],a[1]-P[sh.v[0]-1][1]]:[b[0]-a[0],b[1]-a[1]]);const L=Math.hypot(u[0],u[1])||1;return [u[0]/L,u[1]/L];}
function shapeLimits(sh){const P=sh.l.pts;const u=shapeAxis(sh);const i0=sh.v[0],i1=sh.v[sh.v.length-1];const dot=(p,q)=>(p[0]-q[0])*u[0]+(p[1]-q[1])*u[1];
  const min=i0>0?-(dot(P[i0],P[i0-1])-0.3):0;const max=i1<P.length-1?(dot(P[i1+1],P[i1])-0.3):0;return {min:Math.min(0,+min.toFixed(2)),max:Math.max(0,+max.toFixed(2))};}
function shapeShift(sh,d){const lim=shapeLimits(sh);if(d<lim.min-1e-9||d>lim.max+1e-9){flash(`Pas la place : possible de ${fmt(lim.min)} à ${fmt(lim.max)} m`);return false;}const u=shapeAxis(sh);snapshot();const old=sh.l.pts.map(p=>p.slice());sh.v.forEach(i=>{sh.l.pts[i]=[sh.l.pts[i][0]+u[0]*d,sh.l.pts[i][1]+u[1]*d];});remapLine(sh.l,old);rebuild();shapeBar();flash(`${sh.kind==='lyre'?'Lyre':'Baïonnette'} décalée de ${(d>0?'+':'')+fmt(d)} m`);return true;}
function shapeFlip(sh){if(sh.kind!=='lyre')return false;const P=sh.l.pts;const a=P[sh.v[0]];const u=shapeAxis(sh);snapshot();const old=P.map(p=>p.slice());[sh.v[1],sh.v[2]].forEach(i=>{const p=P[i];const t=(p[0]-a[0])*u[0]+(p[1]-a[1])*u[1];const q=[a[0]+u[0]*t,a[1]+u[1]*t];P[i]=[2*q[0]-p[0],2*q[1]-p[1]];});remapLine(sh.l,old);rebuild();shapeBar();flash('Lyre inversée (de l\'autre côté de l\'axe)');return true;}
function shapeDelete(sh){return delVertices(sh.l,sh.v,sh.kind==='lyre'?'Lyre supprimée (4 sommets)':'Baïonnette supprimée (2 sommets)')>0;}
function shapeBar(){let b=$('#shapeBar');const sh=shapeOfSel();if(!sh||state.mode!=='select'){if(b)b.remove();return;}if(!b){b=document.createElement('div');b.id='shapeBar';b.style.cssText='position:absolute;left:50%;bottom:52px;transform:translateX(-50%);background:#1c3d6b;color:#fff;border-radius:14px;padding:8px 10px;display:flex;gap:6px;align-items:center;font-size:13px;box-shadow:0 6px 20px rgba(0,0,0,.3);flex-wrap:wrap;justify-content:center;max-width:96%;z-index:7';main.appendChild(b);}
  const lim=shapeLimits(sh);const bt=(d,t)=>`<button class="btn sm" data-sh="d|${d}" style="min-height:40px;min-width:44px;background:#fff;color:#1c3d6b;border-color:#fff;font-weight:800" ${d<lim.min-1e-9||d>lim.max+1e-9?'disabled':''}>${t}</button>`;
  b.innerHTML=`<span style="font-weight:800">${sh.kind==='lyre'?'Lyre':'Baïonnette'} <span style="opacity:.8;font-weight:500">sommets ${sh.v[0]}–${sh.v[sh.v.length-1]}</span></span>${bt(-1,'◀ 1 m')}${bt(-0.1,'◀ 0,1')}<input class="f" id="shD" type="number" step="0.1" value="1" style="width:64px;height:40px;text-align:center;font-weight:800;border-radius:10px;border:0" aria-label="décalage en mètres"><button class="btn sm" data-sh="go" style="min-height:40px;background:#fff;color:#1c3d6b;border-color:#fff;font-weight:800">Décaler</button>${bt(0.1,'0,1 ▶')}${bt(1,'1 m ▶')}<span style="opacity:.7;font-size:11.5px">possible : ${fmt(lim.min)} à +${fmt(lim.max)} m</span>${sh.kind==='lyre'?`<button class="btn sm" data-sh="flip" style="min-height:40px;background:#fff;color:#1c3d6b;border-color:#fff;font-weight:800">⇅ Inverser</button>`:''}<button class="btn sm danger" data-sh="del" style="min-height:40px;font-weight:800">🗑 Supprimer</button><button class="btn sm" data-sh="x" style="min-height:40px;min-width:40px;background:#fff;color:#0b0b0b;border-color:#fff" aria-label="fermer">✕</button>`;
  b.onclick=e=>{const x=e.target.closest('[data-sh]');if(!x)return;const k=x.dataset.sh;const S2=shapeOfSel();if(!S2)return;if(k==='x'){state.selV=[];render();renderPanel();shapeBar();return;}if(k==='flip'){shapeFlip(S2);return;}if(k==='del'){if(confirm(`Supprimer cette ${S2.kind==='lyre'?'lyre (4 sommets)':'baïonnette (2 sommets)'} ? L'axe redevient droit, les barres se recalent.`))shapeDelete(S2);return;}
    if(k==='go'){const d=+(($('#shD')||{}).value||0);if(d)shapeShift(S2,d);return;}if(k.startsWith('d|')){const d=+k.slice(2);shapeShift(S2,d);}};}
// ✂ Raccourcir à PK m : sommets au-delà retirés, pièces au-delà retirées (confirmées), REFUSÉ si une antenne part au-delà ; les pièces avant gardent leur PK
function shortenLine(l,m){if(!l)return false;const L=polyLen(l.pts);m=+(+m).toFixed(2);if(!(m>=0.5)){flash('Longueur trop courte (0,5 m mini)');return false;}if(m>=L-0.05){flash(`« ${l.name} » fait déjà ${fmt(L)} m : rien à raccourcir`);return false;}
  const kids=state.lines.filter(x=>x.parent&&x.parent.line===l.id&&x.parent.m>m+0.01);if(kids.length){flash(`Impossible : ${kids.length>1?'les antennes':'l\'antenne'} ${kids.map(k=>`« ${k.name} » (PK ${fmt(k.parent.m)} m)`).join(', ')} ${kids.length>1?'partent':'part'} au-delà de PK ${fmt(m)} m — supprime-la ou raccourcis moins`);return false;}
  const lbl=sp=>sp.type==='tee'&&sp.vert?pvLabel(sp):sp.type==='tee'?'té':sp.type==='valve'?'vanne':sp.type==='reducer'?'réduction →DN'+sp.dn2:sp.type;
  const gone=(l.specials||[]).filter(sp=>!sp.atEnd&&sp.m>m+0.01);const goneD=(l.drapeaux||[]).filter(d=>d.m1>m+0.01);
  if((gone.length||goneD.length)&&!confirm(`Raccourcir « ${l.name} » à ${fmt(m)} m (au lieu de ${fmt(L)} m) :\n${gone.length?`• ${gone.length} pièce(s) au-delà retirée(s) : ${gone.map(sp=>lbl(sp)+' PK '+fmt(sp.m)).join(', ')}\n`:''}${goneD.length?`• ${goneD.length} drapeau(x) retiré(s)\n`:''}Continuer ?`))return false;
  snapshot();const old=l.pts;l.pts=dedupePts(subPoly(old,0,m));if(l.pts.length<2){const q=ptAt(old,m);l.pts=[old[0].slice(),[q.x,q.y]];} // (un sommet à moins de 5 cm du point d'arrêt est fusionné avec lui)
  l.specials=(l.specials||[]).filter(sp=>!gone.includes(sp));l.drapeaux=(l.drapeaux||[]).filter(d=>!goneD.includes(d));if(!l.drapeaux.length)delete l.drapeaux;l.cuts=(l.cuts||[]).filter(c=>c.m<m-0.05);if(!l.cuts.length)delete l.cuts;
  state.selV=[];state.sel={kind:'line',id:l.id};rebuild();flash(`« ${l.name} » raccourcie à ${fmt(polyLen(l.pts))} m${gone.length?` — ${gone.length} pièce(s) retirée(s)`:''}${goneD.length?` — ${goneD.length} drapeau(x) retiré(s)`:''}`);return true;}
// DN d'une ligne (fiche) : toute la ligne JUSQU'À la première réduction (le DN après réduction — dn2 — ne bouge pas) ; les antennes gardent leur DN ; la barre repasse au défaut du DN
function setLineDn(l,dn){if(!l||!(dn>0)||dn===l.dn)return false;const old=l.dn;snapshot();l.dn=dn;l.bar=undefined;
  const reds=(l.specials||[]).filter(s=>s.type==='reducer'&&s.dn2).sort((a,b)=>a.m-b.m);const r1=reds[0]||null;const warn=[];
  (l.specials||[]).forEach(s=>{if(s.type==='tee'&&s.vert&&s.dnb&&s.dnb>dn&&(!r1||s.m<=r1.m)){warn.push(`${pvLabel(s)} PK ${fmt(s.m)} : branche DN${s.dnb} > DN${dn}, remise au DN par défaut`);s.dnb=undefined;}});
  if(r1&&r1.dn2>=dn)warn.push(`la réduction PK ${fmt(r1.m)} (→ DN${r1.dn2}) n'est plus une réduction : à revoir`);
  const kids=state.lines.filter(x=>x.parent&&x.parent.line===l.id&&(!r1||x.parent.m<=r1.m)&&x.dn>dn);if(kids.length)warn.push(`antenne(s) plus grosse(s) que la ligne : ${kids.map(k=>k.name+' DN'+k.dn).join(', ')}`);
  rebuild();flash(`« ${l.name} » : DN${old} → DN${dn} ${r1?`jusqu'à la réduction PK ${fmt(r1.m)} m (DN${r1.dn2} ensuite, inchangé)`:'sur toute la ligne'}${kids.length||warn.length?' — '+warn.join(' ; '):''}`);return true;}
function delLine(id){const kids=state.lines.filter(l=>l.parent&&l.parent.line===id).map(l=>l.id);kids.forEach(delLine);state.lines=state.lines.filter(l=>l.id!==id);if(state.sel&&state.sel.id===id)state.sel=null;if(state.tracing&&state.tracing.resume===id)state.tracing=null;if(state.shorten&&state.shorten.line===id)setMode('select');rebuild();renderTraceForm();}
let flashT=0,flashOld=null; // 14/10 : deux messages à la suite ne se restaurent plus l'un l'autre (on revient au texte d'AVANT le premier) ; un texte posé entre-temps (changement de mode) est gardé
function flash(msg){const h=$('#hint');if(flashT)clearTimeout(flashT);else flashOld={txt:h.textContent,disp:h.style.display};h.textContent=msg;h.style.display='block';
  flashT=setTimeout(()=>{flashT=0;const o=flashOld;flashOld=null;if(h.textContent!==msg||!o)return;h.textContent=o.txt;h.style.display=state.mode==='select'?'none':o.disp;},1600);}
function openAddModal(l,m){const M=$('#modal');const dns=cat.dns();$('#modalBody').innerHTML=`<h3 style="margin:0 0 6px">Ajouter une pièce sur ${esc(l.name)} — PK ${fmt(m)} m</h3><label>Pièce</label><select class="f" id="addType" style="width:100%"><option value="vertex">Sommet (nouveau point de coude, à glisser ensuite)</option><option value="valve">Vanne</option><option value="reducer">Réduction (changement de DN)</option><option value="pv">Té de purge / vidange (branche verticale)</option><option value="tee">Té d'attente (départ d'antenne future, sans tracé)</option><option value="lyre">Lyre de dilatation (4 sommets exacts)</option><option value="jog">Baïonnette (décalage exact)</option><option value="drapeau">Drapeau (une conduite passe au-dessus de l'autre)</option></select><div id="addExtra"></div><label>Position</label><select class="f" id="addPos" style="width:100%"></select><label>PK (m)</label><input class="f" id="addM" type="number" step="0.01" value="${m.toFixed(2)}" style="width:100%"><div class="actions"><button class="btn" id="addCancel">Annuler</button><button class="btn on" id="addOk">Ajouter</button></div>`;
  // positions aimantées : collé à la pièce rigide précédente / suivante (fin de jambe de coude, bout d'un té…), ou sur la soudure la plus proche — d'après la conduite aller
  const posOptions=(t)=>{const B=state.built[l.id];if(!B)return [];const cd=B.A;const Lp=(t==='tee'||t==='pv')?cat.tee(l.dn,l.dn).L:t==='valve'?cat.valve(l.dn).L:t==='reducer'?cat.reducer(l.dn,l.dn).L:t==='endcap'?cat.endcap(l.dn).L:1;
    const rig=cd.pieces.filter(p=>p.kind!=='tube');const prev=rig.filter(p=>p.m1<=m+0.01).sort((a,b)=>b.m1-a.m1)[0],next=rig.filter(p=>p.m0>=m-0.01).sort((a,b)=>a.m0-b.m0)[0];const opts=[{v:m,lbl:`PK cliqué : ${fmt(m)} m`}];
    if(prev&&m-prev.m1<12)opts.push({v:+(prev.m1+Lp/2).toFixed(3),lbl:`collé après ${prev.id} (${prev.kind==='bend'?'fin de jambe du coude':prev.kind}) → PK ${fmt(prev.m1+Lp/2)} m`});
    if(next&&next.m0-m<12)opts.push({v:+(next.m0-Lp/2).toFixed(3),lbl:`collé avant ${next.id} (${next.kind==='bend'?'début de jambe du coude':next.kind}) → PK ${fmt(next.m0-Lp/2)} m`});
    const w=cd.welds.slice().sort((a,b)=>Math.abs(a.m-m)-Math.abs(b.m-m))[0];if(w&&Math.abs(w.m-m)<6)opts.push({v:+(w.m+Lp/2).toFixed(3),lbl:`à la soudure ${w.id} (PK ${fmt(w.m)}) → la pièce commence là`});
    return opts;};
  const extra=()=>{const t=$('#addType').value;const po=posOptions(t);const sel=$('#addPos');if(sel){sel.innerHTML=po.map((o,i)=>`<option value="${o.v}">${esc(o.lbl)}</option>`).join('');sel.onchange=()=>{$('#addM').value=(+sel.value).toFixed(2);};}$('#addExtra').innerHTML=t==='drapeau'?`<label>Longueur du tronçon en drapeau (m)</label><input class="f" id="addDrapL" type="number" step="0.5" value="20" style="width:100%"><label>Conduite qui passe dessus</label><select class="f" id="addDrapTop" style="width:100%"><option value="A">aller</option><option value="R">retour</option></select><label>Coudes du jeu en altimétrie</label><select class="f" id="addDrapA" style="width:100%"><option value="15">2 × 15°</option><option value="30">2 × 30°</option><option value="45">2 × 45°</option></select><div class="muted">La conduite du dessus se rabat sur l'axe de l'autre en montant d'un entraxe (${fmt(cat.casing(l.dn)+rules.entraxeSup)} m) : déplacement ${fmt((cat.casing(l.dn)+rules.entraxeSup)*Math.SQRT2)} m pris par deux coudes ; à la fin, l'inverse. Le tracé compte les coudes et soudures et dessine la conduite du dessous en pointillé.</div>`:t==='valve'?`<label>Disposition des deux vannes</label><select class="f" id="addStagger" style="width:100%"><option value="0">côte à côte (même PK sur l'aller et le retour)</option><option value="q">en quinconce (la vanne retour décalée)</option></select><div id="addStaggerD" style="display:none"><label>Décalage du retour (m, + = vers l'aval)</label><input class="f" id="addStagD" type="number" step="0.1" value="${(cat.valve(l.dn).L+0.5).toFixed(1)}" style="width:100%"></div>`:t==='reducer'?`<label>Nouveau DN (après la réduction)</label><select class="f" id="addDn2" style="width:100%">${dns.map(d=>`<option ${d===l.dn?'selected':''}>${d}</option>`).join('')}</select>`:t==='tee'?`<label>DN de l'antenne</label><select class="f" id="addDnb" style="width:100%">${dns.map(d=>`<option ${d===l.dn?'selected':''}>${d}</option>`).join('')}</select><label>Côté</label><select class="f" id="addSide" style="width:100%"><option value="1">gauche (dans le sens du tracé)</option><option value="-1">droite</option></select><label>Type de té (conduite côté antenne)</label><select class="f" id="addTeeType" style="width:100%">${cat.teeTypes().map(k=>`<option ${k===rules.teeTypeParDefaut?'selected':''}>${k}</option>`).join('')}</select><div class="muted">Deux tés côte à côte : té droit côté branche, ${sautType()?'té à saut ('+esc(sautType())+') sur l\'autre conduite (branche par-dessus la conduite voisine)':'même type sur l\'autre conduite'}.</div>`:t==='pv'?`<label>Type</label><select class="f" id="addPvKind" style="width:100%"><option value="up">Purge — branche vers le haut ▲ (point haut)</option><option value="down">Vidange — branche vers le bas ▼ (point bas)</option><option value="vup">Vidange — té droit, branche vers le haut ▲ (vidange haute)</option></select><label>DN de la branche</label><select class="f" id="addPvDn" style="width:100%">${dns.filter(d=>d<=l.dn).map(d=>`<option value="${d}" ${d===(rules.purgeDN||25)?'selected':''}>${d}</option>`).join('')}</select><div class="muted">Té posé sur l'aller et le retour au même PK, branche verticale (symbole sur le tracé) ; 2 soudures par té. La prise de vue se fait ensuite dans la fiche de la pièce (📷). Purge : DN ${rules.purgeDN||25} par défaut ; vidange : DN ${rules.vidangeDN||40} — vers le bas (point bas) ou par un té droit vers le haut (14/10, Ethan) : même comptage, comptée en vidange.</div>`:'';};
  extra();$('#addType').onchange=extra;M.classList.add('show');$('#addCancel').onclick=()=>M.classList.remove('show');
  $('#modalBody').addEventListener('change',e=>{if(e.target.id==='addStagger'){const d=$('#addStaggerD');if(d)d.style.display=e.target.value==='q'?'':'none';}if(e.target.id==='addPvKind'){const d=$('#addPvDn');if(d)d.value=String(e.target.value==='up'?(rules.purgeDN||25):(rules.vidangeDN||40));}}); /* 14/10 : vidange haute (vup) = DN de vidange */
  $('#addOk').onclick=()=>{const t=$('#addType').value;if(t==='lyre'||t==='jog'){M.classList.remove('show');openShapeModal(t,l,+$('#addM').value);return;}
    if(t==='vertex'){const mm=+$('#addM').value;const q=ptAt(l.pts,Math.max(0,Math.min(polyLen(l.pts),mm)));snapshot();l.pts.splice(q.i,0,[q.x,q.y]);M.classList.remove('show');state.sel={kind:'line',id:l.id};state.selV=[{line:l.id,i:q.i}];setMode('select');rebuild();flash('Sommet inséré à PK '+fmt(mm)+' m — glisse-le');return;}
    if(t==='drapeau'){const m0=+$('#addM').value;const Ld=+$('#addDrapL').value||20;(l.drapeaux=l.drapeaux||[]).push({id:'dp'+Date.now().toString(36),m0,m1:Math.min(polyLen(l.pts),m0+Ld),top:$('#addDrapTop').value,angle:+$('#addDrapA').value});M.classList.remove('show');state.sel={kind:'line',id:l.id};rebuild();return;}const sp={id:'sp'+Date.now().toString(36),type:t,m:+$('#addM').value};if(t==='reducer')sp.dn2=+$('#addDn2').value;if(t==='valve'&&$('#addStagger')&&$('#addStagger').value==='q')sp.staggerR=+$('#addStagD').value;if(t==='tee'){sp.dnb=+$('#addDnb').value;sp.side=+$('#addSide').value;sp.teeType=$('#addTeeType').value;}if(t==='pv'){sp.type='tee';Object.assign(sp,pvFromValue($('#addPvKind').value));sp.dnb=+$('#addPvDn').value;} /* 14/10 : vert = sens de la branche, pvKind = nature (purge / vidange) */snapshot();(l.specials=l.specials||[]).push(sp);M.classList.remove('show');state.sel={kind:'line',id:l.id};rebuild();};}
$('#panel').addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act;
  if(act==='selLine'){state.sel={kind:'line',id:el.dataset.line};state.tab='sel';render();renderPanel();}
  if(act==='selWeld'){state.sel={kind:'weld',id:el.dataset.id};render();renderPanel();}
  if(act==='delLine'){if(confirm('Supprimer cette ligne ?'))delLine(el.dataset.line);}
  if(act==='renameLine'){const l=state.lines.find(x=>x.id===el.dataset.line);l.name=$('#lineName').value||l.name;rebuild();}
  if(act==='invLine'){const l=state.lines.find(x=>x.id===el.dataset.line);l.inv=!l.inv;rebuild();}
  if(act==='delSpecial'){const l=state.lines.find(x=>x.id===el.dataset.line);const sp=(l.specials||[]).find(s=>s.id===el.dataset.sid);snapshot();l.specials=(l.specials||[]).filter(s=>s.id!==el.dataset.sid);if(state.sel&&state.sel.kind==='piece')state.sel={kind:'line',id:l.id};rebuild();if(sp)flash(`${sp.type==='tee'&&sp.vert?pvLabel(sp):sp.type==='tee'?'té d\'attente':sp.type==='valve'?'vanne':sp.type==='reducer'?'réduction':sp.type} PK ${fmt(sp.m)} supprimée (Ctrl+Z pour annuler)`);} /* 14/10 : depuis le plan (fiche de la pièce) comme depuis la fiche de la ligne */
  if(act==='delPhoto'){const l=state.lines.find(x=>x.id===el.dataset.line);const sp=(l.specials||[]).find(s=>s.id===el.dataset.sid);if(sp)delete sp.photo;rebuild();}
  if(act==='delDrap'){const l=state.lines.find(x=>x.id===el.dataset.line);snapshot();l.drapeaux=(l.drapeaux||[]).filter(s=>s.id!==el.dataset.sid);if(state.sel&&state.sel.kind==='piece')state.sel={kind:'line',id:l.id};rebuild();flash('Drapeau supprimé (ses coudes de jeu avec)');}
  // 14/10 (édition du tracé) : reprendre une ligne en pause, raccourcir (clic ou longueur), supprimer / montrer un sommet
  if(act==='resumeLine')resumeLine(el.dataset.line);
  if(act==='shortenLine'){const l=state.lines.find(x=>x.id===el.dataset.line);if(!l)return;if(state.mode==='shorten'&&state.shorten&&state.shorten.line===l.id){setMode('select');return;}setMode('shorten');state.shorten={line:l.id,cursor:null};state.sel={kind:'line',id:l.id};render();renderPanel();$('#hint').textContent=`✂ « ${l.name} » (${fmt(polyLen(l.pts))} m) : clique sur la ligne à l'endroit où elle doit s'arrêter — sommets et pièces au-delà retirés. Échap pour annuler.`;}
  if(act==='shortenTo'){const l=state.lines.find(x=>x.id===el.dataset.line);const v=parseFloat(String(($('#shortLen')||{}).value||'').replace(',','.'));if(!l)return;if(!isFinite(v)){flash('Saisis la longueur voulue (m)');return;}shortenLine(l,v);}
  if(act==='delVertex'){const l=state.lines.find(x=>x.id===el.dataset.line);if(l){delVertex(l,+el.dataset.i);shapeBar();}}
  if(act==='delAligned'){const l=state.lines.find(x=>x.id===el.dataset.line);if(l){const A=alignedVtx(l);delVertices(l,A,`${A.length} sommet${A.length>1?'s':''} aligné${A.length>1?'s':''} retiré${A.length>1?'s':''}`);}} /* 23/10 */
  if(act==='nudge'){nudgeSel(+el.dataset.dx||0,+el.dataset.dy||0);}if(act==='vtxNone'){state.selV=[];render();renderPanel();shapeBar();}
  if(act==='delSelVtx'){const V=(state.selV||[]).slice();const byL={};V.forEach(v=>{(byL[v.line]=byL[v.line]||[]).push(v.i);});if(!confirm(`Supprimer ${V.length} sommets ?`))return;Object.keys(byL).forEach(id=>{const L=state.lines.find(x=>x.id===id);if(L)delVertices(L,byL[id],`${byL[id].length} sommets supprimés sur ${L.name}`);});}
  if(act==='selVtx'){if(e.target.closest('button'))return;const l=state.lines.find(x=>x.id===el.dataset.line);if(!l)return;const i=+el.dataset.i;const on=(state.selV||[]).some(v=>v.line===l.id&&v.i===i);if(state.vtxSel||e.shiftKey)state.selV=on?state.selV.filter(v=>!(v.line===l.id&&v.i===i)):[...(state.selV||[]),{line:l.id,i}];else state.selV=on?[]:[{line:l.id,i}];state.sel={kind:'line',id:l.id};render();renderPanel();shapeBar();}
  if(act==='delCut'){const l=state.lines.find(x=>x.id===el.dataset.line);snapshot();l.cuts=(l.cuts||[]).filter(s=>s.id!==el.dataset.sid);rebuild();}
  // 14/10 (multi-plans) : onglet Fond — un plan actif (encadré), outils de calage par plan
  if(act==='fitPlans')fitPlans();
  if(act==='selPlan'){if(e.target.tagName==='INPUT'||e.target.tagName==='LABEL')return;const id=el.dataset.plan;if(state.bg&&state.bg.active!==id){bgObj().active=id;renderBg();bgToolsSync();renderPanel();}}
  if(act==='delPlan'){const p=bgPlan(el.dataset.plan);if(p&&confirm(`Retirer le plan « ${p.name||p.id} » ?`))removePlan(p.id);}
  if(act==='plScale'||act==='plMove'||act==='plCal2'){bgObj().active=el.dataset.plan;renderBg();bgToolsSync();const m={plScale:'scale',plMove:'moveBg',plCal2:'cal2'}[act];setMode(state.mode===m?'select':m);}
  if(act==='plLayers'){bgObj().active=el.dataset.plan;openDxfModal(bgPlan(el.dataset.plan));}
  if(act==='plInfo'){bgObj().active=el.dataset.plan;openDxfInfo(bgPlan(el.dataset.plan));}});
$('#panel').addEventListener('input',e=>{const t=e.target;if(t.classList.contains('plOp')){const p=bgPlan(t.dataset.plan);if(!p)return;p.opacity=(+t.value)/100;renderBg();saveBg();if(bgActive()===p)$('#bgOp').value=t.value;}});
$('#panel').addEventListener('change',e=>{const t=e.target;
  if(t.classList.contains('plEye')){const p=bgPlan(t.dataset.plan);if(!p)return;p.show=t.checked;renderBg();saveBg();}
  else if(t.classList.contains('plRot')){const p=bgPlan(t.dataset.plan);if(!p)return;const v=parseFloat(String(t.value).replace(',','.'));if(!isFinite(v))return;rotatePlan(p,v);renderBg();saveBg();renderPanel();}
  else if(t.id==='plAll'){bgObj().show=t.checked;renderBg();saveBg();renderDisp();$('#bgShow').checked=t.checked;}
  else if(t.id==='bgAdd2'){const fs=[...t.files];t.value='';addPlanFiles(fs);}});
function renderFondTab(){const P=bgPlans();const a=bgActive();const bg=state.bg;let h=`<h3>Fond de plan${P.length?' ('+P.length+' plan'+(P.length>1?'s':'')+')':''}</h3><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:8px"><label class="btn sm" title="DXF, PDF (une page = un plan), images PNG, JPG…">＋ Ajouter un plan (DXF, PDF, image)<input type="file" id="bgAdd2" accept="${fonds.ACCEPT}" multiple style="display:none"></label>${P.length?`<button class="btn sm" data-act="fitPlans">⤢ Tout voir</button><label class="muted" style="font-size:12px"><input type="checkbox" id="plAll" ${bg&&bg.show!==false?'checked':''}> afficher le fond</label>`:''}</div>`+fonds.fondSection(); /* 14/10 soir (T2) : vue aérienne */
  if(!P.length)return h+`<div class="muted">Aucun plan de fond. <b>＋ Ajouter un plan</b> : DXF (plan du BE, géomètre), PDF (une page = un plan) ou image (scan, capture d'écran, photo de plan) — plusieurs fichiers à la fois (un chantier de 15 antennes = 15 petits plans).<br><br>Chaque plan se cale ensuite ici, en mètres du tracé :<br>• <b>📏 Échelle</b> : deux points du plan + la distance réelle — ou <b>1/N</b> (PDF, image + dpi) ;<br>• <b>✥ Déplacer</b> : glisser le plan ;<br>• <b>⟲ 2 points</b> : deux points du plan, puis les deux mêmes endroits sur le tracé déjà calé → échelle, rotation et position d'un coup ;<br>• <b>rotation</b> en degrés.<br>Les DXF dans le même repère Lambert (même origine) se placent tout seuls, « calés par leurs coordonnées ». Les autres plans arrivent à côté du précédent, à caler.</div>`;
  P.forEach(p=>{const t=tfNorm(p.transform);const on=a&&a.id===p.id;const geo=p.kind==='dxf'&&p.geo==='coords'?'calé par ses coordonnées':p.geo==='aerien'?'calé sur la vue aérienne':p.geo==='manual'?'calé à la main':'<span style="color:#b8560f">à caler</span>';
    h+=`<div class="card" data-act="selPlan" data-plan="${esc(p.id)}" style="cursor:pointer;${on?'border-color:#1c3d6b;box-shadow:0 0 0 1px #1c3d6b':''}"><div style="display:flex;align-items:center;gap:6px"><input type="checkbox" class="plEye" data-plan="${esc(p.id)}" ${p.show!==false?'checked':''} title="afficher / masquer ce plan"><b style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(p.name||'')}">${p.kind==='dxf'?'📐':p.from==='pdf'?'📄':'🖼'} ${esc(p.name||p.id)}</b><button class="btn sm danger" data-act="delPlan" data-plan="${esc(p.id)}" title="retirer ce plan">✕</button></div>
      <div class="muted" style="font-size:11.5px;margin-top:3px">${p.kind==='dxf'?`DXF · ${(p.drawing||[]).length} traits${t.k!==1?' · ×'+fmt(t.k):''}`:`image ${p.image?p.image.pw+' × '+p.image.ph+' px':''} · ${fmt(t.k*1000)} mm/px`} · ${geo}${t.rot?` · ${fmt(t.rot)}°`:''}${fonds.planInfo(p)}</div>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:5px"><label class="muted" style="font-size:11.5px">opacité <input type="range" class="plOp" data-plan="${esc(p.id)}" min="10" max="100" value="${Math.round((p.opacity===undefined?.5:p.opacity)*100)}" style="width:70px;vertical-align:middle"></label><label class="muted" style="font-size:11.5px">rotation <input class="f plRot" data-plan="${esc(p.id)}" type="number" step="0.5" value="${+t.rot.toFixed(2)}" style="width:64px"> °</label></div>${fonds.scaleRow(p)}
      <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:5px"><button class="btn sm ${on&&state.mode==='scale'?'on':''}" data-act="plScale" data-plan="${esc(p.id)}" title="deux points du plan + distance réelle">📏 Échelle</button><button class="btn sm ${on&&state.mode==='moveBg'?'on':''}" data-act="plMove" data-plan="${esc(p.id)}" title="glisser le plan">✥ Déplacer</button><button class="btn sm ${on&&state.mode==='cal2'?'on':''}" data-act="plCal2" data-plan="${esc(p.id)}" title="2 points du plan, puis les 2 mêmes endroits sur le tracé déjà calé : échelle + rotation + position d'un coup">⟲ 2 points</button>${p.kind==='dxf'?`<button class="btn sm" data-act="plLayers" data-plan="${esc(p.id)}" title="calques du réseau, étendue, détail">⚙</button><button class="btn sm" data-act="plInfo" data-plan="${esc(p.id)}" title="rapport de fidélité">ⓘ</button>`:''}${fonds.planBtns(p)}</div></div>`;});
  h+=`<div class="muted" style="font-size:11.5px">Le plan encadré en bleu est le plan <b>actif</b> : les outils du bandeau (📏 ✥ ⟲ opacité ✕ ⚙ ⓘ) agissent sur lui. ${P.length>1?'Les DXF dans le même repère (même origine Lambert) se placent tout seuls ; les autres arrivent à côté du précédent, à caler. ⤢ Tout voir cadre l\'ensemble.':''}</div>`;return h;}
$('#bUndo').onclick=undo;$('#bRedo').onclick=redo;
$$('.tabs button').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderPanel();});
$('#mTrace').onclick=()=>setMode('trace');$('#mSelect').onclick=()=>setMode('select');$('#mAdd').onclick=()=>setMode('add');
{const b=$('#mOne');if(b)b.onclick=()=>{state.one=!state.one;b.classList.toggle('on',state.one);flash(state.one?'Un seul côté : la soudure ou la pièce glissée ne bouge que sur SA conduite (la pièce d\'en face reste)':'La paire : aller et retour bougent ensemble');renderFoot();};}
$('#zIn').onclick=()=>{const v=state.view;const cx=svg.clientWidth/2,cy=svg.clientHeight/2;const nk=v.k*1.3;v.tx=cx-(cx-v.tx)*nk/v.k;v.ty=cy-(cy-v.ty)*nk/v.k;v.k=nk;applyView();render();};
$('#zOut').onclick=()=>{const v=state.view;const cx=svg.clientWidth/2,cy=svg.clientHeight/2;const nk=v.k/1.3;v.tx=cx-(cx-v.tx)*nk/v.k;v.ty=cy-(cy-v.ty)*nk/v.k;v.k=nk;applyView();render();};
$('#zFit').onclick=fitAll;$('#offscreen').onclick=fitAll;
// panneau 👁 : cases d'affichage
function renderDisp(){const d=$('#disp');if(!d||!d.classList.contains('show'))return;const S=state.show;const hasBg=bgPlans().length>0;const bgOn=hasBg&&state.bg.show!==false;
  d.innerHTML=`<b>Affichage</b>`+SHOW_KEYS.map(([k,l])=>{const off=T1.dispOff(k);const on=(k==='fond'?bgOn:S[k])&&!off;const dis=((k==='fond'||k==='textes'||k==='couleurs')&&!hasBg)||off; /* 14/10 soir (lot T1) : étude → marché, écarts, TS désactivés ; chantier → pas de versions */return `<label class="${on&&!dis?'':'off'}"><input type="checkbox" data-k="${k}" ${on?'checked':''} ${dis?'disabled':''}> ${l}</label>`;}).join('')+`<div class="row"><button class="btn sm" data-all="1">Tout</button><button class="btn sm" data-all="0">Épuré</button></div>`;}
function toggleDisp(force){const d=$('#disp');const on=force===undefined?!d.classList.contains('show'):force;d.classList.toggle('show',on);$('#zEye').classList.toggle('on',on);renderDisp();}
function applyShow(k){if(k==='fond'){renderBg();saveBg();return;}if(k==='textes'||k==='couleurs'){bgPlans().forEach(p=>p._lastKey=null);renderBg();return;}if(k==='grille'){renderGrid();return;}render();}
$('#zEye').onclick=()=>toggleDisp();
$('#disp').addEventListener('change',e=>{const k=e.target.dataset.k;if(!k)return;if(k==='fond'){bgObj().show=e.target.checked;}else state.show[k]=e.target.checked;saveShow();applyShow(k);renderDisp();});
$('#disp').addEventListener('click',e=>{const b=e.target.closest('[data-all]');if(!b)return;const on=b.dataset.all==='1';SHOW_KEYS.forEach(([k])=>{if(k==='fond')return;state.show[k]=on||k==='manch'||k==='nums';});saveShow();renderGrid();bgPlans().forEach(p=>p._lastKey=null);renderBg();render();renderDisp();});
svg.addEventListener('pointerdown',()=>{if($('#disp').classList.contains('show'))toggleDisp(false);},{capture:true});
function fitBox(x0,y0,x1,y1){if(x0>x1){state.view={k:6,tx:80,ty:80};}else{const W=svg.clientWidth,H=svg.clientHeight;const m=Math.max(10,(x1-x0)*.06);x0-=m;x1+=m;y0-=m;y1+=m;const k=Math.min(W/(x1-x0),H/(y1-y0));state.view={k,tx:(W-(x1-x0)*k)/2-x0*k,ty:(H-(y1-y0)*k)/2-y0*k};}applyView();render();save();}
function linesBox(){let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;state.lines.forEach(l=>l.pts.forEach(p=>{x0=Math.min(x0,p[0]);y0=Math.min(y0,p[1]);x1=Math.max(x1,p[0]);y1=Math.max(y1,p[1]);}));return x0>x1?null:[x0,y0,x1,y1];}
function fitAll(){let L=linesBox();if(!L){const b=bgBBox();if(b)L=b;} // on cadre sur le réseau ; le fond (souvent un plan de plusieurs km) seulement s'il n'y a rien de tracé — 14/10 (multi-plans) : emprise des plans visibles
  if(!L)fitBox(1,0,0,0);else fitBox(L[0],L[1],L[2],L[3]);}
// ⤢ Tout voir (14/10, multi-plans) : le réseau ET tous les plans de fond (15 antennes réparties dans la ville = la vue d'ensemble une fois calés)
function fitPlans(){const L=linesBox();const b=bgBBox();let B=L&&b?[Math.min(L[0],b[0]),Math.min(L[1],b[1]),Math.max(L[2],b[2]),Math.max(L[3],b[3])]:(L||b);if(!B){fitAll();return;}fitBox(B[0],B[1],B[2],B[3]);}
$('#bClear').onclick=()=>{if(confirm('Effacer toutes les lignes ?')){state.lines=[];state.sel=null;state.selV=[];state.tracing=null;state.shorten=null;if(state.mode==='shorten')setMode('select');rebuild();renderTraceForm();}};
/* ================= passerelle TRACÉ ================= */
const HANDOFF='trace:handoff:';
/* ================= fond de plan : PLUSIEURS plans (DXF et/ou images), chacun calé — 14/10 (multi-plans) =================
   Ethan : « certains chantiers ne sont pas une continuité mais 15 antennes réparties dans la ville : importer plusieurs plans, les décalquer, puis la vue d'ensemble ».
   state.bg = {plans:[plan…], show (tout le fond), active (id du plan sur lequel agissent 📏 ✥ ⟲ opacité ✕ ⚙ ⓘ), origin (repère commun = origine Lambert du 1er DXF)}
   plan = {id, kind:'dxf'|'image', name, show, opacity, transform:{tx,ty,rot,k}, geo:'coords' (DXF placé tout seul par ses coordonnées) | 'manual' (calé à la main) | null (à caler),
           dxf → drawing (repère local), bbox, origin, netLayers, images, report · image → image:{src,pw,ph}} — modèle et maths : src/plans.js.
   Un chantier d'avant (un DXF + une image) devient 1 ou 2 plans sans rien ressaisir ; les clés localStorage / IndexedDB d'avant sont relues et migrées. */
function bgObj(){if(!state.bg)state.bg={plans:[],show:true,active:null,origin:null};const b=state.bg;if(!Array.isArray(b.plans))b.plans=[];if(b.show===undefined)b.show=true;return b;}
const bgPlans=()=>(state.bg&&Array.isArray(state.bg.plans))?state.bg.plans:[];
const bgPlan=id=>bgPlans().find(p=>p.id===id)||null;
function bgActive(){const P=bgPlans();if(!P.length)return null;return P.find(p=>p.id===state.bg.active)||P[P.length-1];}
const planVisible=p=>!!p&&p.show!==false&&!!(state.bg&&state.bg.show!==false);
const bgBBox=all=>plansBBox(bgPlans(),all?null:planVisible); // emprise monde des plans visibles (all : de tous)
// emprise SERRÉE d'un plan (les traits eux-mêmes, sans la marge de 200 m gardée dans bbox pour le cadrage) : cadre du plan actif, placement « à côté »
const planTight=p=>p.kind==='dxf'&&p.drawing&&p.drawing.length?(p._tb||(p._tb=drawingBox(p.drawing))||planLocalBBox(p)):planLocalBBox(p);
const bgTightBBox=()=>{let out=null;bgPlans().forEach(p=>{const b=tfBBox(p.transform,planTight(p));if(!b)return;out=out?[Math.min(out[0],b[0]),Math.min(out[1],b[1]),Math.max(out[2],b[2]),Math.max(out[3],b[3])]:b;});return out;};
const planLabel=p=>p?(p.kind==='dxf'?'📐 ':'🖼 ')+(p.name||p.id):'';
// ce que la passerelle (bridge.js) reçoit à l'enregistrement : les plans, le repère commun, l'œil global
const bgForBridge=()=>{const P=bgPlans().filter(p=>!p.mutuTmp); /* lot MU : l'étude en cours de calage n'est jamais un plan du chantier */const geo=fonds.siteGeo();if(!P.length)return geo?{plans:[],geo}:null;return {plans:P,origin:state.bg.origin||null,show:state.bg.show!==false,active:state.bg.active||null,geo};}; // 14/10 soir (T2) : + géoréférencement du traceur (vue aérienne) → site.geo
let planSeq=1;const newPlanId=()=>{let id;do{id='p'+Date.now().toString(36)+(planSeq++).toString(36);}while(bgPlan(id));return id;};
// un plan qui arrive sans calage se pose À CÔTÉ de ce qui est déjà là (à droite de l'emprise des autres plans et du réseau), jamais empilé au même endroit
function placeBeside(plan){const b=planTight(plan);if(!b)return;const t=tfNorm(plan.transform);const wb=tfBBox(t,b);const P=bgTightBBox(),L=linesBox();const U=P&&L?[Math.min(P[0],L[0]),Math.min(P[1],L[1]),Math.max(P[2],L[2]),Math.max(P[3],L[3])]:(P||L);
  if(!U||!wb)return;const gap=Math.max(5,(U[2]-U[0])*.05);plan.transform={...t,tx:t.tx+(U[2]+gap-wb[0]),ty:t.ty+(U[1]-wb[1])};}
function addPlan(plan,opts={}){const b=bgObj();plan.id=plan.id||newPlanId();if(plan.show===undefined)plan.show=true;if(plan.opacity===undefined)plan.opacity=.5;plan.transform=tfNorm(plan.transform);plan._lastKey=null;b.plans.push(plan);b.active=plan.id;if(!opts.silent){renderBg();if(state.tab==='fond')renderPanel();}return plan;}
function removePlan(id){const b=bgObj();const i=b.plans.findIndex(p=>p.id===id);if(i<0)return false;b.plans.splice(i,1);if(b.active===id)b.active=b.plans.length?b.plans[b.plans.length-1].id:null;delete dxfCtxById[id];if(!b.plans.length&&!state.lines.length)state.bg=null; /* plus rien ni personne dessus : fond vraiment vide (le repère commun ne sert plus) */renderBg();saveBg();saveBgIDB();if(state.tab==='fond')renderPanel();return true;}
function bgToolsSync(){const P=bgPlans();const tools=$('#bgTools');if(!P.length){tools.style.display='none';return;}tools.style.display='inline-flex';const a=bgActive();$('#bgOp').value=Math.round((a&&a.opacity!==undefined?a.opacity:.5)*100);$('#bgShow').checked=state.bg.show!==false;const isD=!!(a&&a.kind==='dxf');$('#bgLayers').style.display=isD?'':'none';$('#bgInfo').style.display=isD?'':'none';$('#bgClear').title=a?'retirer le plan « '+(a.name||a.id)+' »':'retirer le fond';}
// clé de rendu d'un plan : la vue (zoomé : seulement les traits visibles, donc aussi la transform), les cases 👁 textes / couleurs, l'opacité
function planKey(p){const v=state.view;const t=tfNorm(p.transform);const k=v.k*t.k;if(p.kind==='image')return 'img';const zoomed=k>=2&&p.drawing.length>300;return (zoomed?`${Math.round(k*100)}:${Math.round(v.tx)}:${Math.round(v.ty)}:${tfSVG(t)}`:'full:'+Math.round(Math.log2(k)*4))+':'+(state.show.textes!==false?'t':'')+(state.show.couleurs!==false?'c':'')+':'+Math.round((p.opacity===undefined?.5:p.opacity)*100);}
function renderBg(){const P=bgPlans();if(!P.length){gBg.innerHTML='';gBg.dataset.plans='';bgToolsSync();return;}bgToolsSync();
  if(state.bg.show===false){gBg.innerHTML='';gBg.dataset.plans='';P.forEach(p=>p._lastKey=null);return;}
  const vis=P.filter(p=>p.show!==false);const ids=vis.map(p=>p.id).join('|');
  if(gBg.dataset.plans!==ids){gBg.innerHTML=vis.map(p=>`<g class="plan" data-plan="${esc(p.id)}"></g>`).join('')+'<g id="bgSel"></g>';gBg.dataset.plans=ids;P.forEach(p=>p._lastKey=null);} // un <g> par plan, dans l'ordre d'ajout (le dernier dessus)
  const v=state.view;const k=v.k;const W=svg.clientWidth,H=svg.clientHeight;const gs=[...gBg.querySelectorAll('g.plan')];
  vis.forEach((p,i)=>{const g=gs[i];if(!g)return;const t=tfNorm(p.transform);g.setAttribute('transform',tfSVG(t));const op=p.opacity===undefined?.5:p.opacity;g.setAttribute('opacity',p.kind==='image'?op:1);
    const key=planKey(p);if(p._lastKey===key)return;p._lastKey=key;
    if(p.kind==='image'){g.innerHTML=`<image href="${p.image.src}" x="0" y="0" width="${p.image.pw}" height="${p.image.ph}" preserveAspectRatio="none"/>`;return;}
    // DXF : zoomé → seulement les traits visibles (fenêtre ramenée dans le repère du plan — un chemin de plusieurs km à fort zoom fait disparaître tout le calque dans Chrome) ; vue entière → fond allégé
    const ke=k*t.k;const zoomed=ke>=2&&p.drawing.length>300;let box=null;if(!p._bb)p._bb=drawingBBoxes(p.drawing);
    if(zoomed){const mx=W*.5/k,my=H*.5/k;box=tfBBox(tfInverse(t),[(-v.tx)/k-mx,(-v.ty)/k-my,(W-v.tx)/k+mx,(H-v.ty)/k+my]);}
    else if(p._far===undefined){const np=p.drawing.reduce((s,d)=>s+(d.pts?d.pts.length:(d.loops?d.loops.reduce((x,q)=>x+q.length,0):0)),0);p._far=np>60000?decimateDrawing(p.drawing,{cap:45000,simp:0.5,minLen:1.5}).drawing:null;} // vue entière : fond allégé (un téléphone ne peint pas 200 000 points)
    let h=drawingSVG(zoomed?p.drawing:(p._far||p.drawing),{k:ke,box,bb:zoomed?p._bb:null,texts:ke>=4&&(state.show.textes!==false||!!p.mutuTmp),colors:state.show.couleurs!==false||!!p.mutuTmp,op:Math.min(1,op+.3),fillOp:Math.min(1,op+.3)}).svg;
    // images externes référencées par le DXF (ortho-photo…) : le fichier n'est pas dans le DXF → cadre + nom
    (p.images||[]).forEach(im=>{if(!im.pts||im.pts.length<3)return;const p0=im.pts[0];h+=`<path d="M${im.pts.map(q=>q[0]+' '+q[1]).join('L')}Z" fill="none" stroke="#b8560f" stroke-width="1.2" stroke-dasharray="6 4" vector-effect="non-scaling-stroke" opacity=".7"/><text x="${p0[0]+4/ke}" y="${p0[1]+14/ke}" font-size="${12/ke}" fill="#b8560f" font-family="system-ui,sans-serif">image externe (absente du DXF) : ${esc(String(im.path).split(/[\\/]/).pop())}</text>`;});
    g.innerHTML=h;});
  renderBgSel();}
// cadre pointillé + nom du plan actif (pendant un calage, ou onglet Fond ouvert) : on sait sur quel plan on agit
function renderBgSel(){fonds.onMode(); /* 14/10 soir (T2) : appelé à chaque changement de mode */const g=gBg.querySelector('#bgSel');if(!g)return;const a=bgActive();const on=['scale','moveBg','cal2'].includes(state.mode)||state.tab==='fond';const b=a&&on&&planVisible(a)?planTight(a):null;if(!b){g.innerHTML='';return;}
  const k=state.view.k;const t=tfNorm(a.transform);const cs=[[b[0],b[1]],[b[2],b[1]],[b[2],b[3]],[b[0],b[3]]].map(q=>tfApply(t,q));const wb=tfBBox(t,b);
  g.innerHTML=`<path d="M${cs.map(q=>q[0]+' '+q[1]).join('L')}Z" fill="none" stroke="#1c3d6b" stroke-width="1.5" stroke-dasharray="6 4" vector-effect="non-scaling-stroke" opacity=".85"/><text x="${wb[0]}" y="${wb[1]-6/k}" font-size="${12/k}" fill="#1c3d6b" font-weight="600" stroke="#fff" stroke-width="${3/k}" paint-order="stroke" font-family="system-ui,sans-serif">${esc(planLabel(a))}${a.geo==='coords'?' · calé par ses coordonnées':a.geo==='aerien'?' · calé sur la vue aérienne':a.geo==='manual'?'':' · à caler'}</text>`;}
// pendant un glisser : seule la transform du <g> bouge (pas de redessin) ; le contenu zoomé est refait au rAF suivant
function bgQuick(p){const i=bgPlans().filter(x=>x.show!==false).indexOf(p);const g=gBg.querySelectorAll('g.plan')[i];if(g)g.setAttribute('transform',tfSVG(p.transform));renderBgSel();renderBgIfNeeded();}
let bgRaf=0;function renderBgIfNeeded(){fonds.onView(); /* 14/10 soir (T2) : tuiles de la vue aérienne (appelé par applyView) */const P=bgPlans();if(!P.length||state.bg.show===false)return;if(!P.some(p=>p.kind==='dxf'&&p.show!==false&&p._lastKey!==planKey(p)))return;if(bgRaf)cancelAnimationFrame(bgRaf);bgRaf=requestAnimationFrame(()=>{bgRaf=0;renderBg();});}
/* ---- stockage par contexte (SLOT) : un RÉSUMÉ léger en localStorage (calages, œil, opacité — jamais une image ni des traits), le CONTENU dans IndexedDB (bg:dxf = conteneur de tous les plans) ---- */
function bgSummary(){const b=state.bg;if(!b||!b.plans.length)return null;return {v:2,show:b.show!==false,active:b.active||null,origin:b.origin||null,plans:b.plans.filter(p=>!p.mutuTmp).map(p=>{const o={id:p.id,kind:p.kind,name:p.name||'',show:p.show!==false,opacity:p.opacity===undefined?.5:p.opacity,transform:tfNorm(p.transform),geo:p.geo||null};if(p.kind==='dxf'){o.bbox=p.bbox||null;o.origin=p.origin||null;o.netLayers=p.netLayers||[];o.n=p.drawing?p.drawing.length:0;}else{o.pw=p.image&&p.image.pw;o.ph=p.image&&p.image.ph;}return o;})};}
function saveBg(){try{const s=bgSummary();if(!s){localStorage.removeItem(SLOT('trace:bg:v1'));return;}localStorage.setItem(SLOT('trace:bg:v1'),JSON.stringify(s));}catch(e){flash('Mémoire du navigateur pleine : le calage des plans ne sera pas retrouvé après rechargement (il reste dans le chantier enregistré)');}}
function loadBg(){try{const s=JSON.parse(localStorage.getItem(SLOT('trace:bg:v1'))||'null');if(!s)return;const b=bgObj();
  if(s.v===2&&Array.isArray(s.plans)){b.show=s.show!==false;b.active=s.active||null;b.origin=s.origin||null;b._summary=s.plans;return;} // le contenu arrive d'IndexedDB (loadBgIDB) ; ce résumé donne les calages (plus récents)
  if(s.image&&s.image.src){const p=imagePlanFromLegacy(s.image,s.name,s.opacity);if(p){p._migrate=true;addPlan(p,{silent:true});b.show=s.show!==false;}}}catch(e){}} // ancien format (l'image était en localStorage) : reprise, puis rangée dans IndexedDB
async function saveBgIDB(){const b=state.bg;if(!b||!b.plans.length){await kv.del(SLOT('bg:dxf'));return true;}
  const plans=b.plans.filter(p=>!p.mutuTmp).map(p=>{const o={...fonds.planMeta(p),id:p.id,kind:p.kind,name:p.name||'',show:p.show!==false,opacity:p.opacity,transform:tfNorm(p.transform),geo:p.geo||null};if(p.kind==='dxf'){o.drawing=p.drawing;o.bbox=p.bbox;o.origin=p.origin||null;o.netLayers=p.netLayers||[];o.images=p.images||[];o.report=p.report||null;}else o.image=p.image;return o;});
  const ok=await kv.set(SLOT('bg:dxf'),{v:2,plans,show:b.show!==false,active:b.active||null,origin:b.origin||null,at:Date.now()});
  if(!ok)flash('Mémoire du navigateur pleine : les plans de fond ne seront pas retrouvés après rechargement (ils restent dans le chantier enregistré)');return ok;}
let bgEpoch=0; // 16/10 (lot TA) : « nouveau réseau » pendant la lecture d'IndexedDB du démarrage → cette lecture ne remet plus les plans du dessin d'avant
async function loadBgIDB(){const ep=bgEpoch;const d=await kv.get(SLOT('bg:dxf'));if(ep!==bgEpoch)return false;const sum=(state.bg&&state.bg._summary)||null;if(state.bg)delete state.bg._summary;let migrate=bgPlans().some(p=>p._migrate);
  if(d&&d.v===2&&Array.isArray(d.plans)){const b=bgObj();d.plans.forEach(p=>{if(!p||bgPlan(p.id))return;const s=sum&&sum.find(x=>x.id===p.id);const o={...p};if(s){o.transform=s.transform;o.show=s.show;o.opacity=s.opacity;o.name=s.name||o.name;o.geo=s.geo||o.geo;}addPlan(o,{silent:true});});if(!b.origin)b.origin=d.origin||null;if(!sum){b.show=d.show!==false;b.active=d.active||b.active;}else b.active=b.active||d.active||null;}
  else if(d&&d.drawing&&d.drawing.length){const p=dxfPlanFromLegacy(d);if(p&&!bgPlan(p.id)){const b=bgObj();addPlan(p,{silent:true});if(!b.origin)b.origin=d.origin||null;migrate=true;}} // ancien format (un seul DXF)
  if(sum){const miss=sum.filter(s=>!bgPlan(s.id));if(miss.length)flash(`${miss.length} plan(s) de fond non retrouvé(s) dans la mémoire du navigateur : ${miss.map(s=>s.name).join(', ')} — à réimporter (ils restent dans le chantier enregistré)`);}
  bgPlans().forEach(p=>{delete p._migrate;});if(state.bg&&!state.bg.plans.length&&!state.bg.origin)state.bg=null; // aucun plan : pas d'objet (un nouveau contexte reste vraiment vide)
  renderBg();if(migrate){saveBg();await saveBgIDB();}return bgPlans().length>0;}
/* ---- ajout de plans : fichiers DXF et/ou images, plusieurs à la fois ; chaque plan arrive à côté du précédent tant qu'il n'est pas calé ---- */
async function addPlanFiles(files){const list=[...(files||[])].filter(Boolean);if(!list.length)return [];const out=[];planches.begin(); /* 16/10 (lot TA) : un import = une étape d'historique (validée à la fin) */
  for(const f of list){try{const fk=fonds.fileKind(f);if(fk.err){alert(f.name+' : '+fk.err);continue;} /* 14/10 soir (T2) : DXF, PDF, images ; DWG, TIFF… → quoi faire */
      const p=fk.kind==='dxf'?await addDxfFile(f):fk.kind==='pdf'?await fonds.addPdf(f):await fonds.addImage(f);if(Array.isArray(p))out.push(...p);else if(p)out.push(p);}
    catch(err){console.error(err);progress(null);alert(f.name+' : '+(err.message||err));}}
  if(out.length){state.tab='fond';renderPanel();saveBg();await saveBgIDB();if(!state.lines.length||out.some(p=>p.geo!=='coords'))fitPlans();if(out.length>1)flash(`${out.length} plans ajoutés — onglet Fond pour les caler (📏 ✥ ⟲, rotation)`);}planches.end();return out;}
async function addImageFile(file){const src=await shrinkImage(file,2200);const dims=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res({pw:im.width,ph:im.height});im.onerror=rej;im.src=src;});return addImagePlan(src,{name:file.name,pw:dims.pw,ph:dims.ph});}
// taille de départ d'une image : 90 % de la largeur de l'écran (on règle ensuite l'échelle avec deux points) ; posée à côté des plans déjà là
function addImagePlan(src,{name,pw,ph}){const v=state.view;const W=svg.clientWidth||800,H=svg.clientHeight||600;const wW=W/v.k;const w=wW*.9;const k=w/pw;const h=ph*k;const wx0=(-v.tx)/v.k,wy0=(-v.ty)/v.k;
  const plan={id:newPlanId(),kind:'image',name:name||'image',show:true,opacity:.5,geo:null,transform:{tx:wx0+wW*.05,ty:wy0+(H/v.k-h)/2,rot:0,k},image:{src,pw,ph}};
  if(bgPlans().length||state.lines.length)placeBeside(plan);addPlan(plan);flash(`Image ajoutée : ${name||''} — règle l'échelle (📏 deux points + distance réelle) ou cale-la par ⟲ 2 points`);return plan;}
// 📏 échelle du plan actif : deux points cliqués + distance réelle → le plan est agrandi / réduit autour du premier point (image ou DXF)
