  const id=ref?ref.id:'trc_'+Date.now().toString(36);const {site,lost,nW}=siteFromTraceur({id,name,supplier:state.supplier,serie:state.serie,lines:state.lines,built:state.built,rules,bg:bgForBridge(),prev:ref?{welds:ref.welds,geo:ref.geo||null,hydro:ref.hydro||null,dhData:ref.dhData||null,stock:ref.stock||null,marche:ref.marche||null,ts:ref.ts||null,elPos:ref.elPos||null,admin:ref.admin||null,qse:ref.qse||null,full:ref.full||null}:null,barDefault:state.bar,prof:state.prof,...T1.bridgeOpts()}); /* 14/10 : profondeur de pose → site.traceur.profondeur */
